<script lang="ts" module>
	import type { HTMLAttributes } from '../../../internal/html-attributes.js';
	import type { PropsWithElement } from '../../../internal/props-with-element.js';
	import type { Props } from '@zag-js/marquee';

	export interface MarqueeRootProps extends Omit<Props, 'id'>, PropsWithElement<'div'>, HTMLAttributes<'div', 'id' | 'dir'> {}
</script>

<script lang="ts">
	import { useMarquee } from '../modules/provider.svelte.js';
	import { MarqueeRootContext } from '../modules/root-context.js';
	import { splitProps } from '@zag-js/marquee';
	import { mergeProps } from '@zag-js/svelte';

	const props: MarqueeRootProps = $props();

	const [marqueeProps, componentProps] = $derived(splitProps(props));
	const { element, children, ...rest } = $derived(componentProps);

	const id = $props.id();
	const marquee = useMarquee(() => ({
		...marqueeProps,
		id: id,
	}));

	const attributes = $derived(mergeProps(marquee().getRootProps(), rest));

	MarqueeRootContext.provide(() => marquee());
</script>

{#if element}
	{@render element(attributes)}
{:else}
	<div {...attributes}>
		{@render children?.()}
	</div>
{/if}
